select
    *
from wms_inventory_use_statistics
where
    statistics_date_id = #{param.statisticsDateId}
  
      and workshop_id in
      
          #{workshopId}
      
  

    and bool_party_a = 1


    and bool_party_a = 0

  
      and warehouse_type = #{param.projectWarehouseType}
  
  
      and basic_class = #{param.basicClass}
  
  
      and classify_id in
      
          #{classifyId}
      
  
  
      and project_id = #{param.projectId}
  
  
      and specification like concat('%', #{param.specification}, '%')
  
  
      and brand like concat('%', #{param.brand}, '%')
  
  
      and thickness like concat('%', #{param.thickness}, '%')
  
  
      and theory_thickness = #{param.theoryThickness}
  
  
      and width = #{param.width}
  
  
      and length = #{param.length}
  
  
      and color like concat('%', #{param.color}, '%')
  
  
      and length >= #{param.minLength}
  
  
      and material_is_whole = #{param.materialIsWhole}

select
    *
from wms_inventory_use_statistics
where
    bool_delete_enum = 0
and bool_party_a = #{param.boolPartyA}
and basic_class = #{param.basicClass}
and classify_id = #{param.classifyId}
and statistics_date_id = #{statisticsDateId}

    and specification = #{param.specification}


    and specification is null


    and model = #{param.model}


    and model is null


    and material_is_whole = #{param.materialIsWhole}


    and material_is_whole is null


    and warehouse_type = #{param.warehouseType}


    and warehouse_type is null


    and project_id = #{param.projectId}


    and project_id is null


    and length = #{param.length}


    and length is null


    and width = #{param.width}


    and width is null


    and thickness = #{param.thickness}


    and thickness is null


    and brand = #{param.brand}


    and brand is null


    and heat_no_and_batch_no = #{param.heatNoAndBatchNo}


    and heat_no_and_batch_no is null


    and color = #{param.color}


    and color is null


    and unit_net = #{param.unitNet}


    and unit_net is null


    and warehouse_id = #{param.warehouseId}


    and warehouse_id is null


    and standard_id = #{param.standardId}


    and standard_id is null


    and workshop_id = #{param.workshopId}


    and workshop_id is null


    and serial_number = #{param.serialNumber}


    and serial_number is null

select GROUP_CONCAT(id order by id SEPARATOR ',' ) from wms_inventory_use_statistics where bool_delete_enum = 0 and statistics_date_id = #{param.statisticsDateId}
and workshop_id in
#{workshopId}
and bool_party_a = 1
and bool_party_a = 0
and warehouse_type = #{param.projectWarehouseType}
and basic_class = #{param.basicClass}
and classify_id in
#{classifyId}
and project_id = #{param.projectId}
and specification like concat('%', #{param.specification}, '%')
and brand like concat('%', #{param.brand}, '%')
and thickness like concat('%', #{param.thickness}, '%')
and theory_thickness = #{param.theoryThickness}
and width = #{param.width}
and length = #{param.length}
and color like concat('%', #{param.color}, '%')
and length >= #{param.minLength}
and material_is_whole = #{param.materialIsWhole}
group by
bool_party_a, basic_class, classify_id, material_is_whole, length, width, thickness, unit_net, standard_id, specification,
brand,
project_id,
workshop_id,
warehouse_id,
color,
heat_no_and_batch_no,
